ALTER TABLE "support_requests" ADD COLUMN "resolution_note" text;--> statement-breakpoint
ALTER TABLE "support_requests" ADD CONSTRAINT "support_requests_resolution_shape" CHECK (("support_requests"."resolved_at" IS NULL) = ("support_requests"."resolution_note" IS NULL) AND ("support_requests"."resolution_note" IS NULL OR ("support_requests"."resolution_note" ~ '[^\t\n\v\f\r \u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]' AND char_length("support_requests"."resolution_note") <= 500)) AND ("support_requests"."resolved_at" IS NULL OR "support_requests"."resolved_at" >= '1000-01-01 00:00:00+00' AND "support_requests"."resolved_at" < '10000-01-01 00:00:00+00'));